def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    alphabet = list(dict.fromkeys(alphabet))
    children = [{}]
    fail = [0]
    bad = [False]

    def add_node() -> int:
        children.append({})
        fail.append(0)
        bad.append(False)
        return len(bad) - 1

    seen = set()
    for pat in banned:
        if not pat or pat in seen:
            continue
        seen.add(pat)
        node = 0
        for ch in pat:
            nxt = children[node].get(ch)
            if nxt is None:
                nxt = add_node()
                children[node][ch] = nxt
            node = nxt
        bad[node] = True

    from collections import deque
    q = deque()
    for ch in alphabet:
        if ch in children[0]:
            v = children[0][ch]
            fail[v] = 0
            q.append(v)
        else:
            children[0][ch] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for ch in alphabet:
            if ch in children[u]:
                v = children[u][ch]
                fail[v] = children[fail[u]][ch]
                if bad[fail[v]]:
                    bad[v] = True
                q.append(v)
            else:
                children[u][ch] = children[fail[u]][ch]

    good = [i for i, flag in enumerate(bad) if not flag]
    index = {node: i for i, node in enumerate(good)}
    k = len(good)
    mat = [[0] * k for _ in range(k)]
    for u in good:
        row = mat[index[u]]
        for ch in alphabet:
            v = children[u][ch]
            if not bad[v]:
                row[index[v]] += 1

    def mul(a, b):
        c = [[0] * k for _ in range(k)]
        for i in range(k):
            ai = a[i]
            ci = c[i]
            for t in range(k):
                ait = ai[t]
                if not ait:
                    continue
                bt = b[t]
                for j in range(k):
                    bij = bt[j]
                    if bij:
                        ci[j] = (ci[j] + ait * bij) % MOD
        return c

    res = [[1 if i == j else 0 for j in range(k)] for i in range(k)]
    base = mat
    exp = n
    while exp:
        if exp & 1:
            res = mul(res, base)
        base = mul(base, base)
        exp >>= 1
    return sum(res[index[0]]) % MOD
